<?php require_once __DIR__.'/../includes/auth.php'; if(admin_user())redirect_to('admin/index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('SELECT * FROM admins WHERE email=? AND status=\'active\'');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){$_SESSION['admin_id']=$u['id'];session_regenerate_id(true);redirect_to('admin/index.php');}$error='Invalid credentials.';}$page_title='Admin Login'; ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?=base_url('assets/css/style.css')?>"><title>Admin Login</title></head><body><main class="wrap"><section class="verify"><h1>Admin Login</h1><?php if($error):?><p><?=$error?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><input name="email" type="email" placeholder="Email" required></p><p><input name="password" type="password" placeholder="Password" required></p><button class="btn">Sign in</button></form></section></main></body></html>
